   167→impl From<BeaconChainError> for GossipDataColumnError {
   168→    fn from(e: BeaconChainError) -> Self {
   169→        GossipDataColumnError::BeaconChainError(e.into())
   170→    }
   171→}
   172→
   173→impl From<BeaconStateError> for GossipDataColumnError {
   174→    fn from(e: BeaconStateError) -> Self {
   175→        GossipDataColumnError::BeaconChainError(BeaconChainError::BeaconStateError(e).into())
   176→    }
   177→}
