   179→/// A wrapper around a `DataColumnSidecar` that indicates it has been approved for re-gossiping on
   180→/// the p2p network.
   181→#[derive(Debug)]
   182→pub struct GossipVerifiedDataColumn<T: BeaconChainTypes, O: ObservationStrategy = Observe> {
   183→    block_root: Hash256,
   184→    data_column: KzgVerifiedDataColumn<T::EthSpec>,
   185→    _phantom: PhantomData<O>,
   186→}
   187→
   188→impl<T: BeaconChainTypes, O: ObservationStrategy> Clone for GossipVerifiedDataColumn<T, O> {
   189→    fn clone(&self) -> Self {
   190→        Self {
   191→            block_root: self.block_root,
   192→            data_column: self.data_column.clone(),
   193→            _phantom: PhantomData,
   194→        }
   195→    }
   196→}
   197→
   198→impl<T: BeaconChainTypes, O: ObservationStrategy> GossipVerifiedDataColumn<T, O> {
   199→    pub fn new(
   200→        column_sidecar: Arc<DataColumnSidecar<T::EthSpec>>,
   201→        subnet_id: DataColumnSubnetId,
   202→        chain: &BeaconChain<T>,
   203→    ) -> Result<Self, GossipDataColumnError> {
   204→        let header = column_sidecar.signed_block_header.clone();
   205→        // We only process slashing info if the gossip verification failed
   206→        // since we do not process the data column any further in that case.
   207→        validate_data_column_sidecar_for_gossip::<T, O>(column_sidecar, subnet_id, chain).map_err(
   208→            |e| {
   209→                process_block_slash_info::<_, GossipDataColumnError>(
   210→                    chain,
   211→                    BlockSlashInfo::from_early_error_data_column(header, e),
   212→                )
   213→            },
   214→        )
   215→    }
   216→
   217→    /// Create a `GossipVerifiedDataColumn` from `DataColumnSidecar` for block production ONLY.
   218→    /// When publishing a block constructed locally, the EL will have already verified the cell proofs.
   219→    /// When publishing a block constructed externally, there will be no columns here.
   220→    pub fn new_for_block_publishing(
   221→        column_sidecar: Arc<DataColumnSidecar<T::EthSpec>>,
   222→        chain: &BeaconChain<T>,
   223→    ) -> Result<Self, GossipDataColumnError> {
   224→        verify_data_column_sidecar(&column_sidecar)?;
   225→
   226→        // Check if the data column is already in the DA checker cache. This happens when data columns
   227→        // are made available through the `engine_getBlobs` method.  If it exists in the cache, we know
   228→        // it has already passed the gossip checks, even though this particular instance hasn't been
   229→        // seen / published on the gossip network yet (passed the `verify_is_unknown_sidecar` check above).
   230→        // In this case, we should accept it for gossip propagation.
   231→        verify_is_unknown_sidecar(chain, &column_sidecar)?;
   232→
   233→        if chain
   234→            .data_availability_checker
   235→            .is_data_column_cached(&column_sidecar.block_root(), &column_sidecar)
   236→        {
   237→            // Observe this data column so we don't process it again.
   238→            if O::observe() {
   239→                observe_gossip_data_column(&column_sidecar, chain)?;
   240→            }
   241→            return Err(GossipDataColumnError::PriorKnownUnpublished);
   242→        }
   243→
   244→        Ok(Self {
   245→            block_root: column_sidecar.block_root(),
   246→            data_column: KzgVerifiedDataColumn::from_execution_verified(column_sidecar),
   247→            _phantom: Default::default(),
   248→        })
   249→    }
   250→
   251→    /// Create a `GossipVerifiedDataColumn` from `DataColumnSidecar` for testing ONLY.
   252→    pub fn __new_for_testing(column_sidecar: Arc<DataColumnSidecar<T::EthSpec>>) -> Self {
   253→        Self {
   254→            block_root: column_sidecar.block_root(),
   255→            data_column: KzgVerifiedDataColumn::__new_for_testing(column_sidecar),
   256→            _phantom: Default::default(),
   257→        }
   258→    }
   259→
   260→    pub fn as_data_column(&self) -> &DataColumnSidecar<T::EthSpec> {
   261→        self.data_column.as_data_column()
   262→    }
   263→
   264→    /// This is cheap as we're calling clone on an Arc
   265→    pub fn clone_data_column(&self) -> Arc<DataColumnSidecar<T::EthSpec>> {
   266→        self.data_column.clone_data_column()
   267→    }
   268→
   269→    pub fn block_root(&self) -> Hash256 {
   270→        self.block_root
   271→    }
   272→
   273→    pub fn slot(&self) -> Slot {
   274→        self.data_column.data.slot()
   275→    }
   276→
   277→    pub fn index(&self) -> ColumnIndex {
   278→        self.data_column.data.index
   279→    }
   280→
   281→    pub fn signed_block_header(&self) -> SignedBeaconBlockHeader {
   282→        self.data_column.data.signed_block_header.clone()
   283→    }
   284→
   285→    pub fn into_inner(self) -> KzgVerifiedDataColumn<T::EthSpec> {
   286→        self.data_column
   287→    }
   288→}
