   290→/// Wrapper over a `DataColumnSidecar` for which we have completed kzg verification.
   291→#[derive(Debug, Derivative, Clone, Encode, Decode)]
   292→#[derivative(PartialEq, Eq)]
   293→#[ssz(struct_behaviour = "transparent")]
   294→pub struct KzgVerifiedDataColumn<E: EthSpec> {
   295→    data: Arc<DataColumnSidecar<E>>,
   296→}
   297→
   298→impl<E: EthSpec> KzgVerifiedDataColumn<E> {
   299→    pub fn new(
   300→        data_column: Arc<DataColumnSidecar<E>>,
   301→        kzg: &Kzg,
   302→    ) -> Result<Self, (Option<ColumnIndex>, KzgError)> {
   303→        verify_kzg_for_data_column(data_column, kzg)
