   347→/// Data column that we must custody
   348→#[derive(Debug, Derivative, Clone, Encode, Decode)]
   349→#[derivative(PartialEq, Eq, Hash(bound = "E: EthSpec"))]
   350→#[ssz(struct_behaviour = "transparent")]
   351→pub struct CustodyDataColumn<E: EthSpec> {
   352→    data: Arc<DataColumnSidecar<E>>,
   353→}
   354→
   355→impl<E: EthSpec> CustodyDataColumn<E> {
   356→    /// Mark a column as custody column. Caller must ensure that our current custody requirements
   357→    /// include this column
   358→    pub fn from_asserted_custody(data: Arc<DataColumnSidecar<E>>) -> Self {
   359→        Self { data }
   360→    }
   361→
   362→    pub fn into_inner(self) -> Arc<DataColumnSidecar<E>> {
   363→        self.data
   364→    }
   365→    pub fn as_data_column(&self) -> &Arc<DataColumnSidecar<E>> {
   366→        &self.data
   367→    }
   368→    /// This is cheap as we're calling clone on an Arc
   369→    pub fn clone_arc(&self) -> Arc<DataColumnSidecar<E>> {
   370→        self.data.clone()
   371→    }
   372→    pub fn index(&self) -> u64 {
