   377→/// Data column that we must custody and has completed kzg verification
   378→#[derive(Debug, Derivative, Clone, Encode, Decode)]
   379→#[derivative(PartialEq, Eq)]
   380→#[ssz(struct_behaviour = "transparent")]
   381→pub struct KzgVerifiedCustodyDataColumn<E: EthSpec> {
   382→    data: Arc<DataColumnSidecar<E>>,
   383→}
   384→
   385→impl<E: EthSpec> KzgVerifiedCustodyDataColumn<E> {
   386→    /// Mark a column as custody column. Caller must ensure that our current custody requirements
   387→    /// include this column
   388→    pub fn from_asserted_custody(kzg_verified: KzgVerifiedDataColumn<E>) -> Self {
   389→        Self {
   390→            data: kzg_verified.to_data_column(),
   391→        }
   392→    }
   393→
   394→    /// Verify a column already marked as custody column
   395→    pub fn new(
   396→        data_column: CustodyDataColumn<E>,
   397→        kzg: &Kzg,
   398→    ) -> Result<Self, (Option<ColumnIndex>, KzgError)> {
   399→        verify_kzg_for_data_column(data_column.clone_arc(), kzg)?;
   400→        Ok(Self {
   401→            data: data_column.data,
   402→        })
   403→    }
   404→
   405→    pub fn reconstruct_columns(
   406→        kzg: &Kzg,
   407→        partial_set_of_columns: &[Self],
   408→        spec: &ChainSpec,
   409→    ) -> Result<Vec<KzgVerifiedCustodyDataColumn<E>>, KzgError> {
   410→        let all_data_columns = reconstruct_data_columns(
   411→            kzg,
   412→            partial_set_of_columns
   413→                .iter()
   414→                .map(|d| d.clone_arc())
   415→                .collect::<Vec<_>>(),
   416→            spec,
   417→        )?;
   418→
   419→        Ok(all_data_columns
   420→            .into_iter()
   421→            .map(|data| {
   422→                KzgVerifiedCustodyDataColumn::from_asserted_custody(KzgVerifiedDataColumn { data })
   423→            })
   424→            .collect::<Vec<_>>())
   425→    }
