   428→        self.data
   429→    }
   430→
   431→    pub fn as_data_column(&self) -> &DataColumnSidecar<E> {
   432→        &self.data
   433→    }
   434→    pub fn clone_arc(&self) -> Arc<DataColumnSidecar<E>> {
   435→        self.data.clone()
   436→    }
