   442→/// Complete kzg verification for a `DataColumnSidecar`.
   443→///
   444→/// Returns an error if the kzg verification check fails.
   445→#[instrument(skip_all, level = "debug")]
   446→pub fn verify_kzg_for_data_column<E: EthSpec>(
   447→    data_column: Arc<DataColumnSidecar<E>>,
   448→    kzg: &Kzg,
   449→) -> Result<KzgVerifiedDataColumn<E>, (Option<ColumnIndex>, KzgError)> {
   450→    let _timer = metrics::start_timer(&metrics::KZG_VERIFICATION_DATA_COLUMN_SINGLE_TIMES);
   451→    validate_data_columns(kzg, iter::once(&data_column))?;
   452→    Ok(KzgVerifiedDataColumn { data: data_column })
   453→}
   454→
   455→/// Complete kzg verification for a list of `DataColumnSidecar`s.
   456→/// Returns an error for the first `DataColumnSidecar`s that fails kzg verification.
   457→///
   458→/// Note: This function should be preferred over calling `verify_kzg_for_data_column`
   459→/// in a loop since this function kzg verifies a list of data columns more efficiently.
   460→pub fn verify_kzg_for_data_column_list<'a, E: EthSpec, I>(
   461→    data_column_iter: I,
   462→    kzg: &'a Kzg,
   463→) -> Result<(), (Option<ColumnIndex>, KzgError)>
   464→where
   465→    I: Iterator<Item = &'a Arc<DataColumnSidecar<E>>> + Clone,
   466→{
   467→    let _timer = metrics::start_timer(&metrics::KZG_VERIFICATION_DATA_COLUMN_BATCH_TIMES);
   468→    validate_data_columns(kzg, data_column_iter)?;
   469→    Ok(())
   470→}
   471→
   472→#[instrument(skip_all, level = "debug")]
   473→pub fn validate_data_column_sidecar_for_gossip<T: BeaconChainTypes, O: ObservationStrategy>(
   474→    data_column: Arc<DataColumnSidecar<T::EthSpec>>,
   475→    subnet: DataColumnSubnetId,
   476→    chain: &BeaconChain<T>,
   477→) -> Result<GossipVerifiedDataColumn<T, O>, GossipDataColumnError> {
   478→    let column_slot = data_column.slot();
   479→    verify_data_column_sidecar(&data_column)?;
   480→    verify_index_matches_subnet(&data_column, subnet, &chain.spec)?;
   481→    verify_sidecar_not_from_future_slot(chain, column_slot)?;
   482→    verify_slot_greater_than_latest_finalized_slot(chain, column_slot)?;
   483→    verify_is_unknown_sidecar(chain, &data_column)?;
   484→
   485→    // Check if the data column is already in the DA checker cache. This happens when data columns
   486→    // are made available through the `engine_getBlobs` method.  If it exists in the cache, we know
   487→    // it has already passed the gossip checks, even though this particular instance hasn't been
   488→    // seen / published on the gossip network yet (passed the `verify_is_unknown_sidecar` check above).
   489→    // In this case, we should accept it for gossip propagation.
   490→    if chain
   491→        .data_availability_checker
   492→        .is_data_column_cached(&data_column.block_root(), &data_column)
   493→    {
   494→        // Observe this data column so we don't process it again.
   495→        if O::observe() {
   496→            observe_gossip_data_column(&data_column, chain)?;
   497→        }
   498→        return Err(GossipDataColumnError::PriorKnownUnpublished);
   499→    }

